89	    public OwnerRestControllerV1(ClinicService clinicService,
90	                                 OwnerMapper ownerMapper,
91	                                 PetMapper petMapper,
92	                                 VisitMapper visitMapper) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
102	        Collection<Owner> owners;
103	        if (lastName != null) {
104	            owners = this.clinicService.findOwnerByLastName(lastName);
105	        } else {
106	            owners = this.clinicService.findAllOwners();
107	        }
108	        if (owners.isEmpty()) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
117	        Owner owner = this.clinicService.findOwnerById(ownerId);
118	        if (owner == null) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
127	        List<String> missingFields = new ArrayList<>();
128	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
129	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
130	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
131	        requireNonBlank(missingFields, "address", normalizedAddress);
132	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
133	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
134	        if (!missingFields.isEmpty()) {
135	            throw new MissingRequiredFieldsException(missingFields);
136	        }
137	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
138	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
139	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
140	        requireDailyLimitNotReached(registrationDate);
141	        requireCityBelowCapacity(ownerFieldsDto.getCity());
142	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
143	        requireUniqueTelephone(normalizedTelephone);
144	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
145	        if (!sharesHousehold) {
146	            requireUniqueHousehold(ownerFieldsDto.getLastName(), normalizedAddress);
147	        }
148	        ownerFieldsDto.setTelephone(normalizedTelephone);
149	        if (ownerFieldsDto.getEmail() != null) {
150	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
151	        }
152	        HttpHeaders headers = new HttpHeaders();
153	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
154	        owner.setAddress(normalizedAddress);
155	        owner.setRegistrationDate(registrationDate);
156	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
157	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
158	        if (sharesHousehold) {
159	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
160	        }
161	        this.clinicService.saveOwner(owner);
162	        AUDIT.info("Owner created id={} customerCode={} registrationDate={}",
163	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
164	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
165	        headers.setLocation(UriComponentsBuilder.newInstance()
166	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
167	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
168	    }
