250	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
251	    @Override
252	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
253	        Owner owner = this.clinicService.findOwnerById(ownerId);
254	        if (owner != null) {
255	            Pet pet = owner.getPet(petId);
256	            if (pet != null) {
257	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
258	            }
259	        }
260	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
261	    }
262	
263	    /**
264	     * Builds the owner's customer code as {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the
265	     * upper-cased first three letters of {@code city}, {@code LAST3} the upper-cased first three letters
266	     * of {@code lastName}, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more
267	     * than the number of owners already in that city (e.g. {@code SYD-SMI-0007}).
268	     *
269	     * @param city the owner's city (already validated non-blank)
270	     * @param lastName the owner's last name (already validated non-blank)
271	     * @return the formatted customer code for the owner being created
272	     */
273	    private String nextCustomerCode(String city, String lastName) {
274	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
275	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
276	        int sequence = (int) this.clinicService.findAllOwners().stream()
277	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
278	            .count() + 1;
279	        return String.format("%s-%s-%04d", city3, last3, sequence);
280	    }
281	
282	    /**
283	     * Counts the existing owners (those already persisted before this create) whose first and last
284	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
285	     * the new owner as its {@code namesakeCount} and echoed back on reads.
286	     *
287	     * @param firstName the incoming owner's first name (already validated non-blank)
288	     * @param lastName the incoming owner's last name (already validated non-blank)
289	     * @return the number of existing namesakes sharing both names case-insensitively
290	     */
291	    private int countNamesakes(String firstName, String lastName) {
292	        return (int) this.clinicService.findAllOwners().stream()
293	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
294	                && lastName.equalsIgnoreCase(existing.getLastName()))
295	            .count();
296	    }
297	
298	    /**
299	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
300	     * whitespace-only), so the caller can reject the request listing every offending field.
301	     */
302	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
303	        if (value == null || value.isBlank()) {
304	            missingFields.add(fieldName);
305	        }
306	    }
307	
308	    /**
309	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
310	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
311	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
312	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
313	     * {@code "+61412345678"}.
314	     *
315	     * @param telephone the raw telephone value from the request
316	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
317	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
318	     */
319	    private static String normalizeTelephone(String telephone) {
320	        String e164 = toE164(telephone);
321	        if (e164 == null) {
322	            throw new InvalidFieldValueException("telephone",
323	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
324	        }
325	        return e164;
326	    }
327	
328	    /**
329	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
330	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
331	     * owners' stored numbers when detecting duplicates.
332	     */
333	    private static String toE164(String telephone) {
334	        if (telephone == null) {
335	            return null;
336	        }
337	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
338	        String digits;
339	        if (cleaned.startsWith("+")) {
340	            digits = cleaned.substring(1);
341	        } else {
342	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
343	            digits = "61" + national;
344	        }
345	        if (!digits.matches("[0-9]{8,15}")) {
346	            return null;
347	        }
348	        return "+" + digits;
349	    }
350	
351	    /**
352	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
353	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
354	     *
355	     * @param email the raw email value from the request (already known to be non-null)
356	     * @return the lower-cased email to be stored and returned
357	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
358	     */
359	    private static String normalizeEmail(String email) {
360	        String trimmed = email.trim();
361	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
362	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
363	        }
364	        return trimmed.toLowerCase(Locale.ROOT);
365	    }
366	
367	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
368	    private static final int MAX_OWNERS_PER_CITY = 50;
369	
370	    /**
371	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
372	     * owners, comparing city names case-insensitively (consistent with the per-city customer-code
373	     * sequence). Callers reach this only once {@code city} has been validated non-blank.
374	     *
375	     * @param city the incoming owner's city (already validated non-blank)
376	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
377	     */
378	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
379	    private static final int MAX_OWNERS_PER_DAY = 100;
380	
381	    /**
382	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
383	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
384	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
385	     * date rolled forward to a business day), so this caps the number that may be created per day.
386	     *
387	     * @param businessDay the adjusted business-day registration date of the owner being created
388	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
389	     */
390	    private void requireDailyLimitNotReached(LocalDate businessDay) {
391	        long registeredThatDay = this.clinicService.findAllOwners().stream()
392	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
393	            .count();
394	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
395	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
396	        }
397	    }
398	
399	    /**
400	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
401	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
402	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
403	     * is recorded on the next business day, and every value derived from the registration date uses the
404	     * adjusted date.
405	     *
406	     * @param date the effective registration date (supplied or defaulted), never {@code null}
407	     * @return the same date, or the next Monday when {@code date} is a weekend
408	     */
409	    private static LocalDate toBusinessDay(LocalDate date) {
410	        DayOfWeek day = date.getDayOfWeek();
411	        if (day == DayOfWeek.SATURDAY) {
412	            return date.plusDays(2);
413	        }
414	        if (day == DayOfWeek.SUNDAY) {
415	            return date.plusDays(1);
416	        }
417	        return date;
418	    }
419	
420	    private void requireCityBelowCapacity(String city) {
421	        long cityOwners = this.clinicService.findAllOwners().stream()
422	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
423	            .count();
424	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
425	            throw new CityAtCapacityException(city);
426	        }
427	    }
428	
429	    /**
430	     * Rejects the request when {@code normalizedTelephone} is already used by any existing owner,
431	     * comparing on the E.164 form so differently-formatted stored numbers still collide.
432	     *
433	     * @param normalizedTelephone the incoming owner's normalized E.164 telephone
434	     * @throws DuplicateTelephoneException if another owner already uses this telephone
435	     */
436	    private void requireUniqueTelephone(String normalizedTelephone) {
437	        boolean taken = this.clinicService.findAllOwners().stream()
438	            .map(Owner::getTelephone)
439	            .map(OwnerRestControllerV1::toE164)
440	            .filter(existing -> existing != null)
441	            .anyMatch(normalizedTelephone::equals);
442	        if (taken) {
443	            throw new DuplicateTelephoneException(normalizedTelephone);
444	        }
445	    }
446	
447	    /**
448	     * Rejects the request when another owner already shares this household, i.e. has both the same
449	     * last name and the same address once each value is normalized (trimmed, internal whitespace
450	     * runs collapsed to a single space, and compared case-insensitively). Callers skip this check
451	     * when the request opts in via {@code sharesHousehold}.
452	     *
453	     * @param lastName the incoming owner's last name (already validated non-blank)
454	     * @param address the incoming owner's address (already validated non-blank)
455	     * @throws DuplicateHouseholdException if another owner already has this last name and address
456	     */
457	    private void requireUniqueHousehold(String lastName, String address) {
458	        String normalizedLastName = normalizeForHousehold(lastName);
459	        String normalizedAddress = householdAddressKey(address);
460	        boolean taken = this.clinicService.findAllOwners().stream()
461	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
462	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress));
463	        if (taken) {
464	            throw new DuplicateHouseholdException(lastName, address);
465	        }
466	    }
467	
468	    /**
469	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
470	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
471	     * comparisons are case-insensitive.
472	     */
473	    private static String normalizeForHousehold(String value) {
474	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
475	    }
476	
477	    /**
478	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
479	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
480	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
481	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
482	     * value normalizes to the empty string, so the required-field check rejects an address that is
483	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
484	     *
485	     * @param address the raw address value from the request (may be {@code null})
486	     * @return the normalized address, or the empty string when blank after normalization
487	     */
488	    private static String normalizeAddress(String address) {
489	        if (address == null) {
490	            return "";
491	        }
492	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
493	        if (collapsed.isEmpty()) {
494	            return "";
495	        }
496	        String[] tokens = collapsed.split(" ");
497	        StringBuilder sb = new StringBuilder();
498	        for (String token : tokens) {
499	            String expanded = switch (token) {
500	                case "ST" -> "STREET";
501	                case "RD" -> "ROAD";
502	                case "AVE" -> "AVENUE";
503	                default -> token;
504	            };
505	            if (sb.length() > 0) {
506	                sb.append(' ');
507	            }
508	            sb.append(expanded);
509	        }
510	        return sb.toString();
511	    }
512	
513	    /**
514	     * Derives the comparison key for an address used by household-duplicate detection and the shared
515	     * household identifier: the address is first put in its canonical normalized form and then
516	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
517	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
518	     */
519	    private static String householdAddressKey(String address) {
520	        return normalizeForHousehold(normalizeAddress(address));
521	    }
522	
523	    /**
524	     * Joins the household identified by this last name and address, returning the stable shared
525	     * {@code householdId} to store on the joining owner. The identifier is derived deterministically
526	     * from the normalized last name and address, so every owner in the same household resolves to the
527	     * same value. Any existing household members that predate this feature (or were created without
528	     * opting in) are back-filled with the shared identifier so the whole household agrees.
529	     *
530	     * @param lastName the joining owner's last name (already validated non-blank)
531	     * @param address the joining owner's address (already validated non-blank)
532	     * @return the shared household identifier for this last name and address
533	     */
534	    private String joinHousehold(String lastName, String address) {
535	        String normalizedLastName = normalizeForHousehold(lastName);
536	        String normalizedAddress = householdAddressKey(address);
537	        String householdId = householdIdFor(normalizedLastName, normalizedAddress);
538	        this.clinicService.findAllOwners().stream()
539	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
540	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
541	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
542	            .forEach(existing -> {
543	                existing.setHouseholdId(householdId);
544	                this.clinicService.saveOwner(existing);
545	            });
546	        return householdId;
547	    }
548	
549	    /**
550	     * Derives a stable household identifier from the already-normalized last name and address as the
551	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
552	     * always maps to the same identifier.
553	     */
554	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
555	        try {
556	            byte[] digest = MessageDigest.getInstance("SHA-256")
557	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
558	            StringBuilder sb = new StringBuilder();
559	            for (byte b : digest) {
560	                sb.append(String.format("%02X", b));
561	            }
562	            return sb.substring(0, 12);
563	        }
564	        catch (NoSuchAlgorithmException e) {
565	            throw new IllegalStateException("SHA-256 not available", e);
566	        }
567	    }
568	}
